// Counter.test.js
import { describe, it, expect } from 'vitest'
import { mount } from '@vue/test-utils'
import Counter from './Counter.vue'

describe('Counter.vue', () => {
  it('renders initial count', () => {
    const wrapper = mount(Counter, { props: { initial: 10 } })
    const countElement = wrapper.find('[data-test="count"]')
    expect(countElement.text()).toBe('10')
  })

  it('increments count when + button is clicked', async () => {
    const wrapper = mount(Counter, { props: { initial: 0 } })
    const incrementBtn = wrapper.find('[data-test="increment"]')
    await incrementBtn.trigger('click')
    const countElement = wrapper.find('[data-test="count"]')
    expect(countElement.text()).toBe('1')
  })

  it('decrements count when - button is clicked', async () => {
    const wrapper = mount(Counter, { props: { initial: 5 } })
    const decrementBtn = wrapper.find('[data-test="decrement"]')
    await decrementBtn.trigger('click')
    const countElement = wrapper.find('[data-test="count"]')
    expect(countElement.text()).toBe('4')
  })

  it('resets count to initial value when reset button is clicked', async () => {
    const wrapper = mount(Counter, { props: { initial: 5 } })
    const incrementBtn = wrapper.find('[data-test="increment"]')
    await incrementBtn.trigger('click')
    await incrementBtn.trigger('click')
    const resetBtn = wrapper.find('[data-test="reset"]')
    await resetBtn.trigger('click')
    const countElement = wrapper.find('[data-test="count"]')
    expect(countElement.text()).toBe('5')
  })

  it('allows decrement below zero', async () => {
    const wrapper = mount(Counter, { props: { initial: 0 } })
    const decrementBtn = wrapper.find('[data-test="decrement"]')
    await decrementBtn.trigger('click')
    const countElement = wrapper.find('[data-test="count"]')
    expect(countElement.text()).toBe('-1')
  })
})
